mapper.select:
SELECT event_id, actor_id, resource_id, summary, follower_cursor, attempts
FROM notification_fanout_job
WHERE status = 'IN_FLIGHT' AND claim_token = #{token}

mapper.update:
UPDATE notification_fanout_job
SET status = CASE WHEN #{dead} THEN 'DEAD' ELSE 'RETRY' END,
    next_attempt_at = DATE_ADD(CURRENT_TIMESTAMP(6), INTERVAL #{backoffSeconds} SECOND),
    claim_token = NULL, lease_until = NULL, last_error = #{error}
WHERE event_id = #{eventId} AND status = 'IN_FLIGHT' AND claim_token = #{token}
